// Abre o rastro que vai costurar mensagem → decisão da IA → gravação.
// O formato é o do padrão W3C: 00-<32 hex>-<16 hex>-01. O SGA-TI lê este
// cabeçalho e pendura o registro dele no MESMO rastro, em vez de criar outro.
const hex = (bytes) => Array.from(
  { length: bytes },
  () => Math.floor(Math.random() * 256).toString(16).padStart(2, '0'),
).join('');

const traceId = hex(16);
const spanId = hex(8);

const entrada = $input.first().json;
// Aceita os formatos mais comuns de quem chama: {mensagem}, {texto}, {body:{...}}.
const corpo = entrada.body || entrada;
const mensagem = String(corpo.mensagem || corpo.texto || corpo.message || '').trim();
const quem = String(corpo.de || corpo.remetente || 'desconhecido').trim();

if (!mensagem) {
  throw new Error('a requisição precisa trazer o campo "mensagem" com o texto do colaborador');
}

return [{
  json: {
    traceId,
    spanId,
    traceparent: `00-${traceId}-${spanId}-01`,
    inicioMs: Date.now(),
    mensagem,
    quem,
  },
}];

// Lê a resposta do Claude. Com tool_choice "any", ele é obrigado a chamar uma
// das duas ferramentas — então ou veio um evento completo, ou veio a pergunta
// do que falta. Não existe caminho em que ele responde texto solto.
const rastro = $('Abrir rastro').first().json;
const resposta = $input.first().json;

if (resposta.error) {
  throw new Error(`a API do Claude respondeu erro: ${JSON.stringify(resposta.error).slice(0, 300)}`);
}

const chamada = (resposta.content || []).find((bloco) => bloco.type === 'tool_use');
if (!chamada) {
  throw new Error(`resposta sem chamada de ferramenta (stop_reason: ${resposta.stop_reason})`);
}

const uso = resposta.usage || {};
const comum = {
  ...rastro,
  acao: chamada.name,
  modelo: resposta.model,
  tokens_entrada: uso.input_tokens ?? 0,
  tokens_saida: uso.output_tokens ?? 0,
  tokens_cache_lidos: uso.cache_read_input_tokens ?? 0,
};

if (chamada.name === 'registrar_evento') {
  // Formato da seção 10 do prompt, que é o que o webhook do SGA-TI espera:
  // `ativo` aninhado e o resto no primeiro nível. Não se declara
  // responsavel_acao: quem define o autor é a chave de API, e um corpo que
  // tenta declarar outro autor é registrado como tentativa de personificação.
  const { evento, ativo, dados_do_evento: detalhes } = chamada.input;
  return [{ json: { ...comum, corpoParaSgaTi: { evento, ativo, ...(detalhes || {}) } } }];
}

return [{ json: { ...comum, ...chamada.input } }];

// Converge os dois caminhos numa resposta só e monta o rastro do Langfuse.
const dados = $input.first().json;
const registrou = dados.acao === 'registrar_evento';
const doSgaTi = registrou ? ($('SGA-TI — registrar evento').first().json || {}) : {};
const aceito = registrou && Boolean(doSgaTi.evento_id);

const resposta = aceito
  ? `Registrado: evento nº ${doSgaTi.evento_id}, ativo nº ${doSgaTi.ativo_id} (${doSgaTi.status_novo}).`
  : registrou
    ? `O SGA-TI recusou: ${doSgaTi.erro || 'motivo não informado'}${
        doSgaTi.detalhes ? ` (${doSgaTi.detalhes.join('; ')})` : ''}`
    : dados.pergunta;

const agoraNs = `${Date.now()}000000`;
const inicioNs = `${dados.inicioMs}000000`;
const atributo = (chave, valor) => (valor === undefined || valor === null
  ? null
  : { key: chave, value: typeof valor === 'number'
      ? { intValue: String(Math.round(valor)) }
      : { stringValue: String(valor) } });

// Formato OTLP/JSON. A API de ingestão do Langfuse é desligada em 16/11/2026;
// o endpoint OpenTelemetry é o caminho recomendado, e é um padrão aberto.
const rastroLangfuse = {
  resourceSpans: [{
    resource: { attributes: [atributo('service.name', 'n8n-sga-ti')] },
    scopeSpans: [{
      scope: { name: 'sga-ti-n8n' },
      spans: [{
        traceId: dados.traceId,
        spanId: dados.spanId,
        name: 'mensagem_para_evento',
        kind: 1,
        startTimeUnixNano: inicioNs,
        endTimeUnixNano: agoraNs,
        status: { code: aceito || !registrou ? 1 : 2 },
        attributes: [
          atributo('langfuse.trace.name', 'mensagem_para_evento'),
          atributo('user.id', dados.quem),
          atributo('gen_ai.request.model', dados.modelo),
          atributo('gen_ai.usage.input_tokens', dados.tokens_entrada),
          atributo('gen_ai.usage.output_tokens', dados.tokens_saida),
          atributo('gen_ai.usage.cache_read_input_tokens', dados.tokens_cache_lidos),
          atributo('sga_ti.acao', dados.acao),
          atributo('sga_ti.aceito', aceito ? 'sim' : 'nao'),
          atributo('sga_ti.evento_id', doSgaTi.evento_id),
          atributo('sga_ti.campos_faltando', (dados.campos_faltando || []).join(', ')),
          // A mensagem original NÃO vai para o rastro: costuma conter nome de
          // pessoa. Só o tamanho dela, que ajuda a investigar sem identificar
          // ninguém. Se o seu Langfuse for próprio e você quiser o conteúdo,
          // troque a linha abaixo por atributo('langfuse.observation.input', dados.mensagem).
          atributo('sga_ti.tamanho_mensagem', dados.mensagem.length),
          atributo('langfuse.observation.output', resposta),
        ].filter(Boolean),
      }],
    }],
  }],
};

return [{ json: { resposta, aceito, rastroLangfuse } }];
